/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: CatalogReviewPreparePhase, CatalogReviewFrozen, CatalogReviewPrepareReview, CatalogReviewRead,
 *          CatalogReviewPrepareInput
 *   Functions: useCatalogReviewPrepare
 *   Constants: catalogReviewRefusals
 * Internal
 *   Types: Mode, Pending, Kept, State
 *   Functions: lagging
 *   Constants: editable, idle, numbersPath
 * @end-catalog */

import { useEffect, useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { adminWorkspace } from './adminWorkspace';
import type { CatalogReview, ReviewDraftChange, ReviewMutation } from './catalogReviewApi';
import type { ApplyChoice, ApplyPositionBlock, ReviewApplyModel, ReviewApplySelection } from './catalogReviewApplyModel';
import type { AdminCommand } from './useAdminCommand';

/**
 * Where requesting the update stands (docs/features/admin-workbench.md, the action bar): `editing` (also after going back or a
 * settled refusal), `saving` the draft before confirming, `saving_only` (the save-only button, or the same-intent retry of a save),
 * `reading` until the detail, lookup summary and identity read show the saved revision, `review_required` (editable: a noted item
 * gained a hold, an identity answer or a shared position, or the server asked for review), `frozen` (the inline confirmation),
 * `applying`, `success`, `stale`, `unknown` (an apply whose outcome is unknown), `querying` (reading the review to settle it),
 * `save_failed` (a refused save; the unsaved values stay, until the editor loads a newer saved draft) and `save_unknown` (a save whose
 * outcome is unknown).
 */
export type CatalogReviewPreparePhase = 'editing' | 'saving' | 'saving_only' | 'reading' | 'review_required' | 'frozen' | 'applying' | 'success' | 'stale'
  | 'unknown' | 'querying' | 'save_failed' | 'save_unknown';
/**
 * The frozen confirmation: the saved review it shows and the selection the apply sends. `extra` says the save advanced the value
 * revision, so release data was found and kept unselected; `saved` whether a save was sent and `numbersSaved` whether it changed
 * a member's Disc or Track Number (the stored candidates were compared again only then, and only when the run completed with them).
 */
export type CatalogReviewFrozen = { item: CatalogReview; selection: ReviewApplySelection; extra: boolean; saved: boolean; numbersSaved: boolean };
/**
 * Why preparing returned to the review: noted items (`keys`) no longer selected or now held, the selected lists' identities that
 * need an answer, the members at one position or outside the bounds, and whether the review changed past the save (`changed`).
 */
export type CatalogReviewPrepareReview = { keys: string[]; identities: string[]; positions: ApplyPositionBlock[]; changed: boolean };
/**
 * A read the selection waits for (the summary and identity queries, as useReviewApplyModel returns them in `reads`); the summary's
 * `waiting` says why a saved review that is otherwise ready cannot be confirmed.
 */
export type CatalogReviewRead = { data?: { revision: number; valueRevision: number; summary?: { waiting: { lookup: boolean; analysis: boolean } } }; isPlaceholderData: boolean;
  isFetching: boolean; isError: boolean; refetch: () => unknown };

/**
 * The refusal names of this hook's own save and apply (`admin.common.<name>`; docs/features/admin-workbench.md, the action bar): a
 * source changed since capture leads to the stale view; a new identity candidate or ID holder, a stale identity answer or a changed
 * decided record returns to the review; a change or lookup application not yet seen reads the review again; active Luna AI has its
 * own message. Sent with each of the hook's runs only, so the page's other operations on the same command (identity decisions,
 * adopting, analysis) keep AdminCommand's generic conflict and the re-reads that follow it. Metadata lookup refusals keep
 * AdminCommand's own `lookup_*` names.
 */
export const catalogReviewRefusals: Readonly<Record<string, string>> = {
  ADMIN_CATALOG_REVIEW_SOURCE_CHANGED: 'stale',
  ADMIN_IMPORT_REVIEW_REQUIRED: 'review_required', ADMIN_IMPORT_DUPLICATE_STALE: 'review_required', ADMIN_CATALOG_REVIEW_IDENTITY_CHANGED: 'review_required',
  ADMIN_IMPORT_REVISION_CONFLICT: 'conflict', ADMIN_IMPORT_FIELD_CONFLICT: 'conflict',
  ADMIN_IMPORT_ANALYSIS_ACTIVE: 'analysis_active'
};

/** What the page gives the hook on every render. */
export interface CatalogReviewPrepareInput {
  /** The review's id. */
  id: string;
  /** The page's review command: `useCatalogReviewCommand(id, { id }).command` (the hook names its own runs' refusals). */
  command: AdminCommand<ReviewMutation>;
  /** The newest saved review the page shows (its detail read, or a newer receipt's item); null while it loads. */
  item: CatalogReview | null;
  /** The saved `item`'s model with the editor's choices and the title proposal: `useReviewApplyModel(item, choices, { proposed }).model`. */
  model: ReviewApplyModel | null;
  /** The reads that model rests on: `useReviewApplyModel(...).reads` (none for a review not captured for lookup). */
  reads: readonly CatalogReviewRead[];
  /** Reads the detail again (the detail query's `refetch`), to settle an unknown apply. */
  refetch: () => Promise<{ data?: { item: CatalogReview }; isError: boolean }>;
  /** The editor's base revision: the save's `expectedRevision`. */
  revision: number;
  /** The unsaved changes a save sends: the edits and only the selected proposals (`reviewDraftChanges`); none skips the save. */
  changes: () => ReviewDraftChange[];
  /** The keys of the items selected on the unsaved draft: `useReviewApplyModel(item, choices, { draft, proposed }).model` items. */
  intended: () => readonly string[];
  /** Merges explicit choices (each `{ checked: false, basis }`) into the editor's choices, for items the save added. */
  onChoices: (choices: Record<string, ApplyChoice>) => void;
}

type Mode = 'prepare' | 'save' | 'apply';
/** This hook's operation in flight or unknown; `only` says a save was save-only (kept when its retry turns a prepare into a save). */
type Pending = { op: string; mode: Mode; only: boolean };
/** What a remount needs to resume that operation, kept in the account-fenced workspace buffer beside the command it ran on. */
type Kept = { op: string; only: boolean; frozen: CatalogReviewFrozen | null };
type State = { phase: CatalogReviewPreparePhase; notice: string | null; saveOnlyFailed: boolean; frozen: CatalogReviewFrozen | null; review: CatalogReviewPrepareReview | null;
  applied: CatalogReview | null; queried: boolean };
/** The phases preparing can start from. */
const editable: readonly CatalogReviewPreparePhase[] = ['editing', 'review_required', 'save_failed'];
const idle: State = { phase: 'editing', notice: null, saveOnlyFailed: false, frozen: null, review: null, applied: null, queried: false };
const numbersPath = /\.(discNumber|trackNumber)$/;
/** Whether a read is not yet the one for the review at `at`'s revision and value revision (a placeholder, or an older answer). */
const lagging = (read: CatalogReviewRead, at: { revision: number; valueRevision: number }) =>
  read.isPlaceholderData || read.data?.revision !== at.revision || read.data.valueRevision !== at.valueRevision;

/**
 * Requesting the update of an existing-Album review (owner rules: docs/business-rules.md, applying an existing-Album review): notes
 * the selection asked for, saves the unsaved values as one ordinary save (skipped when nothing changed), waits until the detail
 * and the reads are at the saved revision and value revision, keeps whatever the save added unselected by explicit choices, then
 * freezes the confirmation or returns to the review when a noted item now waits. Confirming sends the frozen item's revisions and
 * selection. An unknown apply is settled by reading the review: applied by this operation replays its receipt, applied by another
 * shows success, a stale source shows stale, otherwise the same operation may be sent again. Driven by the command's snapshots
 * (AdminCommand.run returns nothing), never by awaiting it.
 *
 * Preparing waits until the reads show the detail's revision (`busy` meanwhile): the noted selection must include the items only
 * those reads list. A pending save or apply resumes after a remount, with its frozen confirmation and whether it was save-only.
 *
 * Returns the state and the actions `prepare`, `saveOnly`, `back`, `confirm`, `queryOutcome` and `retrySame`. The state: `phase`;
 * `notice`, the last outcome's message, always `admin.common.<notice>`: `saved`, `left_confirmation` (after going back), `unknown`,
 * `error` (a read failed), `lookup_active` or `analysis_active` (lookup or Luna AI runs on the saved review), a name from
 * catalogReviewRefusals, or an AdminCommand error name (`reload`, `discarded`, `lookup_*`, `musicbrainz_id_in_use`); `saveOnlyFailed`
 * when the failed or unknown save was save-only; `frozen`; `outdated` when the detail moved past the frozen item; `review`;
 * `applied`, the applied item; `queried` once a read found the apply still pending; `busy`.
 */
export function useCatalogReviewPrepare({ id, command, item, model, reads, refetch, revision, changes, intended, onChoices }: CatalogReviewPrepareInput) {
  const client = useQueryClient(), path = `/catalog-reviews/${id}`, buffer = `catalog-review-prepare:${id}`;
  // A command left pending by an earlier mount (its intent kept) resumes as this review's save (which returns to editing once
  // saved) or apply, with what that mount kept for it.
  const [resume] = useState(() => {
    const { intent, running } = command.getSnapshot();
    const mode: Mode | null = intent?.path === `${path}/apply` ? 'apply' : intent?.path === path && intent.method === 'PATCH' ? 'save' : null;
    if (!intent || !mode) return null;
    const kept = adminWorkspace.buffer<Kept>(buffer), own = kept?.op === intent.operationId ? kept : null;
    return { op: intent.operationId, mode, running, only: own?.only ?? false, frozen: mode === 'apply' ? own?.frozen ?? null : null };
  });
  const [state, setState] = useState<State>(() => !resume ? idle
    : { ...idle, phase: resume.running ? (resume.mode === 'apply' ? 'applying' : 'saving_only') : resume.mode === 'apply' ? 'unknown' : 'save_unknown', notice: resume.running ? null : 'unknown',
      saveOnlyFailed: !resume.running && resume.mode === 'save' && resume.only, frozen: resume.frozen });
  const [owner] = useState(() => { try { return adminWorkspace.capture(); } catch { return null; } });
  const pending = useRef<Pending | null>(resume && { op: resume.op, mode: resume.mode, only: resume.only });
  const running = useRef<string | null>(resume?.running ? resume.op : null);
  const target = useRef({ revision: 0, valueRevision: 0, advanced: false, saved: false, numbersSaved: false });
  const noted = useRef<Set<string>>(new Set()), written = useRef<Set<string>>(new Set()), refetched = useRef<Set<string>>(new Set());
  const reread = () => void client.invalidateQueries({ predicate: query => query.queryKey[0] === 'admin-catalog-reviews' && query.queryKey[4] === id });
  /** Ends this hook's operation: nothing left to resume. */
  const done = () => { pending.current = null; adminWorkspace.forget(buffer); };

  // Each settled run of this hook's own operation moves the state; any other command run on the page is left alone.
  useEffect(() => command.subscribe(() => {
    const snapshot = command.getSnapshot(), mine = pending.current;
    if (snapshot.running) { running.current = snapshot.intent?.operationId ?? null; return; }
    const op = running.current; running.current = null;
    if (!mine || op !== mine.op) return;
    if (snapshot.result?.receipt.operationId === mine.op) {
      done();
      const saved = snapshot.result.item;
      if (mine.mode === 'apply') setState({ ...idle, phase: 'success', applied: saved });
      else if (mine.mode === 'save') setState({ ...idle, notice: 'saved' });
      else {
        target.current = { ...target.current, revision: saved.revision, valueRevision: saved.valueRevision, advanced: saved.valueRevision > target.current.valueRevision };
        setState({ ...idle, phase: 'reading' });
      }
    } else if (snapshot.error === 'unknown' && snapshot.intent?.operationId === mine.op) {
      setState(previous => ({ ...idle, phase: mine.mode === 'apply' ? 'unknown' : 'save_unknown', notice: 'unknown', saveOnlyFailed: mine.mode !== 'apply' && mine.only,
        frozen: mine.mode === 'apply' ? previous.frozen : null }));
    } else if (snapshot.error) {
      // A definite refusal: nothing to retry. Every one reads the review, its summary and its identity rows again.
      done(); reread();
      const error = snapshot.error;
      setState(error === 'stale' ? { ...idle, phase: 'stale', notice: error }
        : mine.mode === 'apply' ? { ...idle, phase: error === 'review_required' ? 'review_required' : 'editing', notice: error }
          : { ...idle, phase: 'save_failed', notice: error, saveOnlyFailed: mine.only });
    }
  }), [command]);
  // A refused save's alert says the unsaved values are kept; once the editor moves to a newer saved draft (the conflict panel's
  // Load saved version), they are not, and the refusal no longer stands: the review is plainly editable again, and the command
  // drops the refusal so the page does not say it either.
  const failedAt = useRef<number | null>(null);
  useEffect(() => {
    if (state.phase !== 'save_failed') failedAt.current = null;
    else if (failedAt.current === null) failedAt.current = revision;
    else if (revision > failedAt.current) { if (command.getSnapshot().error === state.notice) command.settle(); setState(idle); }
  }, [state.phase, revision]);
  // Losing the Admin view or the account (a 401 or 403 resets the workspace) leaves nothing pending here.
  useEffect(() => adminWorkspace.subscribe(() => {
    if (owner && !adminWorkspace.current(owner, false)) { pending.current = null; running.current = null; setState(idle); }
  }), [owner]);

  // Reading: freeze once the detail and every read are at the saved revisions and the choices keep the save's additions out.
  // A detail read (a refresh, a refocus) that shows the review applied or its source no longer current also settles an unknown save
  // or apply: nothing is left to send, so its intent is dropped and the page's other controls (Discard completion) are released.
  useEffect(() => {
    const unknown = state.phase === 'unknown' || state.phase === 'save_unknown';
    if (!item || (state.phase !== 'reading' && state.phase !== 'frozen' && !unknown)) return;
    if (unknown && (item.state === 'applied' || item.sourceStatus !== 'current')) { done(); command.settle(); }
    if (item.state === 'applied') { setState({ ...idle, phase: 'success', applied: item }); return; }
    if (item.sourceStatus !== 'current') { setState({ ...idle, phase: 'stale', notice: 'stale' }); return; }
    if (state.phase !== 'reading' || !model) return;
    const at = target.current;
    if (item.revision < at.revision || item.revision === at.revision && item.valueRevision < at.valueRevision) return;
    if (item.revision > at.revision || item.valueRevision > at.valueRevision) {
      setState({ ...idle, phase: 'review_required', review: { keys: [], identities: [], positions: [], changed: true } }); return;
    }
    if (reads.some(read => read.isError)) { setState({ ...idle, notice: 'error' }); return; }
    const behind = (read: CatalogReviewRead) => lagging(read, item);
    if (reads.some(behind)) {
      // A read answered for this revision before a lookup application advanced the value revision is asked once more.
      reads.forEach((read, index) => {
        const key = `${index}:${item.revision}:${item.valueRevision}`;
        if (behind(read) && !read.isFetching && !read.isPlaceholderData && read.data && !refetched.current.has(key)) { refetched.current.add(key); void read.refetch(); }
      });
      return;
    }
    const keep = noted.current, extra: Record<string, ApplyChoice> = {};
    for (const entry of model.items) {
      if (keep.has(entry.key) || !(at.advanced || entry.selected) || written.current.has(`${entry.key}\n${entry.basis}`)) continue;
      written.current.add(`${entry.key}\n${entry.basis}`); extra[entry.key] = { checked: false, basis: entry.basis };
    }
    if (Object.keys(extra).length) { onChoices(extra); return; }
    // Wait for the explicit choices to reach the model.
    if (model.items.some(entry => entry.selected && !keep.has(entry.key))) return;
    const keys = [...keep].filter(key => { const entry = model.items.find(value => value.key === key); return !entry || !entry.selected || entry.hold !== null; });
    if (keys.length || model.blocking.identities.length || model.blocking.positions.length) {
      setState({ ...idle, phase: 'review_required', review: { keys, identities: model.blocking.identities, positions: model.blocking.positions, changed: false } });
      return;
    }
    // No row waits, so the saved review waits for lookup or Luna AI (started meanwhile, perhaps in another tab): say which.
    if (!model.ready) {
      const waiting = reads.find(read => read.data?.summary)?.data?.summary?.waiting;
      setState({ ...idle, notice: model.blocking.lookup ? 'lookup_active' : waiting?.analysis ? 'analysis_active' : 'error' }); return;
    }
    setState({ ...idle, phase: 'frozen', frozen: { item, selection: JSON.parse(JSON.stringify(model.selection)) as ReviewApplySelection, extra: at.advanced,
      saved: at.saved, numbersSaved: at.numbersSaved } });
  });

  const idleCommand = () => { const snapshot = command.getSnapshot(); return !snapshot.running && !snapshot.intent; };
  /**
   * Runs this hook's own operation with its refusal names and keeps what a remount resumes it with; false when the command did not
   * admit it (another runs, an intent waits, the view changed).
   */
  const send = (mode: Mode, to: string, body: object, method?: string, frozen: CatalogReviewFrozen | null = null) => {
    command.run(to, body, method, catalogReviewRefusals);
    const snapshot = command.getSnapshot();
    if (!snapshot.running || !snapshot.intent) return false;
    const op = snapshot.intent.operationId;
    pending.current = { op, mode, only: mode === 'save' }; running.current = op;
    if (owner) adminWorkspace.retain(buffer, { op, only: mode === 'save', frozen } satisfies Kept, owner);
    return true;
  };
  // The reads still answer for an earlier revision (after a save or a lookup application) or are loading: preparing waits.
  const settling = Boolean(item && (!model || reads.some(read => !read.isError && lagging(read, item))));
  const save = (mode: 'prepare' | 'save') => {
    if (!item || !idleCommand() || !editable.includes(state.phase)) return;
    if (mode === 'prepare') {
      // The noted selection must include what only the reads list (Artist entries, label, tracklist, member Credits).
      if (reads.some(read => read.isError)) { reread(); setState({ ...idle, notice: 'error' }); return; }
      if (settling) return;
    }
    const sent = changes(), asked = intended();
    // Nothing selected: the bar waits, and there is nothing to prepare.
    if (mode === 'prepare' && !asked.length) return;
    noted.current = new Set(asked); written.current = new Set(); refetched.current = new Set();
    target.current = { revision: item.revision, valueRevision: item.valueRevision, advanced: false, saved: sent.length > 0, numbersSaved: sent.some(change => numbersPath.test(change.path)) };
    if (!sent.length) { setState(mode === 'prepare' ? { ...idle, phase: 'reading' } : idle); return; }
    if (send(mode, path, { expectedRevision: revision, changes: sent })) setState({ ...idle, phase: mode === 'prepare' ? 'saving' : 'saving_only' });
  };

  const frozen = state.frozen;
  return {
    ...state,
    outdated: Boolean(frozen && item && (item.revision !== frozen.item.revision || item.valueRevision !== frozen.item.valueRevision)),
    busy: ['saving', 'saving_only', 'reading', 'applying', 'querying'].includes(state.phase) || settling && editable.includes(state.phase),
    /**
     * Saves the unsaved values, then shows the confirmation (or the review, when a noted item now waits). Does nothing while the
     * reads settle or nothing is selected; a failed read is asked again.
     */
    prepare: () => save('prepare'),
    /** Saves the unsaved values without preparing the update. */
    saveOnly: () => save('save'),
    /** Leaves the confirmation (or the review it returned to): the saved draft stays and the original Album is unchanged. */
    back: () => { if (state.phase === 'frozen' || state.phase === 'review_required') setState({ ...idle, notice: 'left_confirmation' }); },
    /** Applies the frozen selection at the frozen item's revision and value revision, even if the detail moved since. */
    confirm: () => {
      if (state.phase !== 'frozen' || !frozen || !idleCommand()) return;
      const { fields, memberCredits, preselections, musicBrainzIds } = frozen.selection;
      if (send('apply', `${path}/apply`, { expectedRevision: frozen.item.revision, fields, memberCredits, preselections, musicBrainzIds,
        expectedValueRevision: frozen.item.valueRevision }, 'POST', frozen)) setState({ ...state, phase: 'applying', notice: null });
    },
    /** Reads the review to settle an unknown apply. */
    queryOutcome: () => {
      const mine = pending.current;
      if (state.phase !== 'unknown' || !mine || command.getSnapshot().running) return;
      setState(previous => ({ ...previous, phase: 'querying' }));
      const settle = (next: State) => { done(); command.settle(); setState(next); };
      void refetch().catch(() => ({ data: undefined, isError: true })).then(({ data, isError }) => {
        if (pending.current?.op !== mine.op) return;
        const found = isError ? undefined : data?.item;
        if (!found) setState(previous => ({ ...previous, phase: 'unknown', notice: 'unknown' }));
        else if (found.state === 'applied' && found.applied?.operationId === mine.op) {
          // Applied by this operation: sending it again replays its stored receipt, which completes it.
          setState(previous => ({ ...previous, phase: 'applying', notice: null })); command.retry();
        } else if (found.state === 'applied') settle({ ...idle, phase: 'success', applied: found });
        else if (found.sourceStatus !== 'current') settle({ ...idle, phase: 'stale', notice: 'stale' });
        else setState(previous => ({ ...previous, phase: 'unknown', queried: true }));
      });
    },
    /** Sends the pending save or apply again with its original operation; a retried save returns to editing once saved. */
    retrySame: () => {
      const mine = pending.current, snapshot = command.getSnapshot();
      if (!mine || snapshot.running || snapshot.intent?.operationId !== mine.op || (state.phase !== 'unknown' && state.phase !== 'save_unknown')) return;
      if (mine.mode !== 'apply') mine.mode = 'save';
      running.current = mine.op;
      setState(previous => ({ ...previous, phase: mine.mode === 'apply' ? 'applying' : 'saving_only', notice: null }));
      command.retry();
    }
  };
}
